<template>
  <section>
    <loader :is-visible="isLoading"></loader>

    <!-- Page Header -->
    <div class="theme-primary partition-full">
      <span class="p-name text-white">{{ Type =='Task' ? $t('ImportTask') :  $t('ImportIssue') }}</span>
      <span class="p-actions float-right">
      
        <a title="" @click="BacktoList()" class="p-action-btn text-white float-right"
                        data-toggle-tooltip="tooltip" data-original-title="Back to list"><i aria-hidden="true"
                            class="fa fa-angle-double-left"></i><br>{{ $t('BacktoList') }}</a>
      </span>
    </div>

    <!-- <div class="heading-border mb-4 mt-2">
      <h5 class="h5"><span>{{ $t('ImportTask') }}</span>    
    <small>
       <a title="" @click="BacktoList()" class="float-right"
                        data-toggle-tooltip="tooltip" data-original-title="Back to list"><i aria-hidden="true"
                            class="fa fa-angle-double-left mr-2"></i>{{ $t('BacktoList') }}</a>
    </small>
    </h5></div> -->



    <div class="tab-style mt-3">
    <div class="tab_container mb-0">
      <!-- Tabs -->
      <ul class="nav nav-tabs all-tabs responsive-tabs cust flex-wrap newtabbb w-100">
        <li class="nav-item">
          <a class="nav-link tab-button" :class="{ active: activeTab === 'excel' }" @click="setActiveTab('excel')" href="javascript:void(0)">
            <em class="fa fa-file-excel-o mr-2"></em>{{ $t('Import To Excel') || 'Excel Import' }}
          </a>
        </li>
        <li class="nav-item">
          <a class="nav-link tab-button" :class="{ active: activeTab === 'global' }" @click="setActiveTab('global')" href="javascript:void(0)">
            <em class="fa fa-globe mr-2"></em>{{Type=='Task' ?  $t('Global Task'):  $t('Global Task') }}
          </a>
        </li>
        <li class="nav-item">
          <a class="nav-link tab-button" :class="{ active: activeTab === 'jiraCsv' }" @click="setActiveTab('jiraCsv')" href="javascript:void(0)">
            <em class="fa fa-file-text-o mr-2"></em>Jira CSV
          </a>
        </li>
        <li class="nav-item">
          <a class="nav-link tab-button" :class="{ active: activeTab === 'jiraApi' }" @click="setActiveTab('jiraApi')" href="javascript:void(0)">
            <em class="fa fa-plug mr-2"></em>Jira API
          </a>
        </li>
      </ul>
      <!-- Tab Panes -->
      <div class="col-12 p-4 float-left border mb-4">
        <!-- Tab 1: Excel Import -->
        <div v-if="activeTab === 'excel'">
          <div class="row align-items-end mb-3">
            <div class="col-12 col-md-4">
              <label class="font-weight-medium">{{ $t('DownloadSampleFile') || 'Download Sample File' }}</label>
              <div>
                <a href="https://cogniterblob.blob.core.windows.net/global/SampleFiles/project/task-import-sample-file.xls"  class="btn btn-info btn-sm" download>
                  <em class="fa fa-download pr-1"></em>{{ $t('DownloadSampleFile') || 'Download Sample' }}
                </a>
              </div>
            </div>
            <div class="col-12 col-md-4">
              <label class="font-weight-medium">{{ $t('UploadFile') || 'Upload File' }}</label>
              <div class="custom-file expenseFile">
                <input type="file" name="FileSrc" id="flAvatar" multiple="true"
                       accept=".xls,.xlsx"
                       @change="setFile($event)"
                       class="custom-file-input" />
                <label class="custom-file-label text-truncate" for="flAvatar">
                  {{ excelFileName || ($t('ChooseFile') || 'Choose file...') }}
                </label>
              </div>
            </div>
            <div class="col-12 col-md-4">
              <button type="button" class="btn btn-success btn-sm" @click="UploadProjectFile()">
                <em class="fa fa-upload pr-1"></em>{{ $t('Import From Excel') || 'Import from Excel' }}
              </button>
              <button type="button" class="btn btn-secondary btn-sm ml-2" @click="Clear()">
                <em class="fa fa-times pr-1"></em>{{ $t('Clear') || 'Clear' }}
              </button>
            </div>
          </div>
        </div>

        <!-- Tab 2: Global Tasks -->
        <div v-if="activeTab === 'global'">
          <div class="row mb-3">
            <div class="col-12 col-md-4">
              <button type="button" class="btn btn-success btn-sm" @click="GlobalImport()">
                <em class="fa fa-globe pr-1"></em>{{Type =='Task' ?  $t('Import From Global Task') || 'Import from Global Task' : 'Import from Global Issue'}}
              </button>
            </div>
          </div>
        </div>

        <!-- Tab 3: Jira CSV -->
        <div v-if="activeTab === 'jiraCsv'">
          <div class="row align-items-end mb-3">
            <div class="col-12 col-md-4">
              <label class="font-weight-medium">Upload Jira CSV Export</label>
              <div class="custom-file">
                <input type="file" class="custom-file-input" id="jiraCsvInput"
                       accept=".csv"
                       @change="setJiraCsvFile($event)" />
                <label class="custom-file-label text-truncate" for="jiraCsvInput">
                  {{ jiraCsvFileName || 'Choose Jira CSV file...' }}
                </label>
              </div>
            </div>
            <div class="col-12 col-md-4 float-right">
              <button type="button" class="btn btn-success btn-sm" @click="UploadJiraCsvFile()">
                <em class="fa fa-upload pr-1"></em>Import Jira CSV
              </button>
            </div>
          </div>
        </div>

        <!-- Tab 4: Jira API -->
        <div v-if="activeTab === 'jiraApi'">
          <div class="row mb-3">
            <div class="col-12 col-md-6">
              <label class="font-weight-medium">Jira Domain <small class="text-muted">(e.g. mycompany)</small></label>
              <input type="text" class="form-control form-control-sm" v-model="jiraCredentials.domain"
                placeholder="mycompany" autocomplete="off" />
            </div>
            <div class="col-12 col-md-6">
              <label class="font-weight-medium">Jira Email</label>
              <input type="email" class="form-control form-control-sm" v-model="jiraCredentials.email"
                placeholder="user@example.com" autocomplete="off" />
            </div>
          </div>
          <div class="row mb-3">
            <div class="col-12 col-md-6">
              <label class="font-weight-medium">API Token</label>
              <input type="password" class="form-control form-control-sm" v-model="jiraCredentials.apiToken"
                placeholder="Jira API token" autocomplete="new-password" />
            </div>
            <div class="col-12 col-md-6">
              <label class="font-weight-medium">Jira Project Key <small class="text-muted">(e.g. PROJ)</small></label>
              <input type="text" class="form-control form-control-sm" v-model="jiraCredentials.projectKey"
                placeholder="PROJ" autocomplete="off" />
            </div>
          </div>
          <div class="row mb-3">
            <div class="col-12">
              <button type="button" class="btn btn-success btn-sm" @click="FetchJiraApiTasks()" :disabled="isFetchingJira">
                <em class="fa pr-1" :class="isFetchingJira ? 'fa-spinner fa-spin' : 'fa-cloud-download'"></em>
                {{ isFetchingJira ? Type=='Task' ? 'Fetching...' : 'Fetch Tasks from Jira' : 'Fetch Issue from Jira'  }}
              </button>
            </div>
          </div>
        </div>

      </div>

      <!-- Preview Table — Excel listing or Jira CSV listing -->
      <div class="row" v-if="activePreviewList != null && activePreviewList.length > 0">
        <div class="col-sm-12 col-md-12 col-lg-12 col-xl-12">
          <div class="col-12 p-0 mt-3 Search-panel" id="divassestsearch">
            <div class="heading-border">
              <h5 class="h5">
                <span v-if="activeTab === 'excel'">{{ $t('Microsoft') }} {{ $t('Excel') }} {{ $t('Listing') }}</span>
                <span v-else-if="activeTab === 'jiraCsv'">Jira CSV Listing</span>
                <span v-else-if="activeTab === 'jiraApi'">Jira API Listing</span>
              </h5>
            </div>
          </div>
          <div class="listing mt-2">
            <div class="table-responsive">
              <table id="Addresslist" class="table table-bordered dt-responsive nowrap mt-0">
                <thead class="thead-bg">
                  <tr>
                    <th class="text-center" style="width:50px !important;" id="nonresize">
                      <div class="custom-control custom-checkbox">
                        <input class="chkItems setcheckall custom-control-input" type="checkbox" id="chkAll"
                          name="checkbox" data-parent="no" style="display: none;" v-model="selectAll" :disabled="IsDisable"
                          @change="toggleSelectAll">
                        <label class="custom-control-label universal-custom-control-label pt-1" for="chkAll"></label>
                      </div>
                    </th>
                    <th class="text-center"><span>{{ Type=='Task' ? $t('Task Name') : $t('Issue Name') }}</span></th>
                    <th class="text-center"><span>{{ $t('Plan Start Date') }}</span></th>
                    <th class="text-center"><span>{{ $t('Plan End Date') }}</span></th>
                    <th class="text-center" v-if="activeTab === 'excel'"><span>{{Type=='Task' ? $t('Parent Task') : $t('Parent Issue')  }}</span></th>
                    <th class="text-center"><span>{{ $t('Description') }}</span></th>
                  </tr>
                </thead>
                <tbody>
                  
                  <tr v-for="(item, index) in activePreviewList" :key="index" class="text-center">
                    <td>
                      <div class="custom-control custom-checkbox">
                        <input class="chkItems setcheckall custom-control-input" type="checkbox" :id="'chkAll_' + index"
                          name="checkbox" data-parent="no" style="display: none;" :disabled="item.IsDisable" v-model="item.selected"
                          v-on:change="singleCheckBox(item)">
                        <label class="custom-control-label universal-custom-control-label pt-1"
                          :for="'chkAll_' + index"></label>
                      </div>
                    </td>
                    <td>{{ item.taskName || item.TaskName }}</td>
                    <td>{{ item.planStartDate || item.PlanStartDate  || item.StartDate}}</td>
                    <td>{{ item.planEndDate || item.PlanEndDate || item.EndDate}}</td>
                    <td v-if="activeTab === 'excel'">
                      <select class="form-control text-center" v-model="item.parentTaskId">
                        <option value="" selected>Select {{Type=='Task' ? $t('Parent Task') : $t('Parent Issue') }}</option>
                        <option v-for="(parenttask, pindex) in parenttaskdata" :key="pindex" :value="parenttask">
                          {{ TruncateStr(parenttask.name, 20) }}
                        </option>
                      </select>
                    </td>
                    <td>{{ parseDescription(item.taskDescription || item.TaskDescription).text }}</td>
                  </tr>
                  <tr v-if="activePreviewList.length == 0">
                    <td colspan="20">
                      <div class="text-center text-danger">{{ $t('NoRecordfound') }}</div>
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>
          </div>
        </div>
        <div class="col-sm-12 col-md-12 col-lg-12 col-xl-12 text-right mt-2">
          <button type="button" class="btn btn-success btn-sm"
            @click="AddBulkFromPreview()">
            <em class="fa fa-plus pr-2"></em><span>{{ $t('Add') }}</span>
          </button>
        </div>
      </div>

      <!-- Task Listing Section -->
      <div class="conversation-date heading-border float-left">
        <span>{{ Type=='Task' ? $t("Task Listing") :$t("Issue Listing")  }}</span>
      </div>
      <Form ref="form">
        <div class="container-fluid collapse show p-0" id="collapseOne1">
          <div class="listing">
            <div class="table-responsive" style="overflow: visible;">
              <table id="Addresslist" class="table table-bordered dt-responsive nowrap mt-0">
                <thead class="thead-bg">
                  <tr>
                    <th class="text-center"><span>{{Type=='Task' ? $t('Task Name') : $t('Issue Name')}}</span></th>
                    <th class="text-center"><span>{{ $t('Plan Start Date') }}</span></th>
                    <th class="text-center"><span>{{ $t('Plan End Date') }}</span></th>
                    <th class="text-center"><span>{{Type=='Task' ? $t('Parent Task Name') : $t('Parent Issue Name') }}</span></th>
                    <th class="text-center"><span>{{ $t('Description') }}</span></th>
                    <th class="text-center"><span>{{ $t('Action') }}</span></th>
                  </tr>
                </thead>
                <tbody>
                  <tr v-for="(item, index) in ListingData" :key="index" class="text-center">
                    <td>
                      <Field :name="+ index + ' Name'" :rules="{ required: true }" v-slot="{ errors }">
                        <input
                          type="text"
                          v-model="item.TaskName"
                          class="form-control"
                          :class="[
                            'form-control',
                            {
                              'is-invalid': errors.length > 0 || item.isDuplicate
                            }
                          ]"
                        />
                      </Field>
                    </td>
                    <!-- Plan Start Date -->
                    <td style="overflow:visible!important;">
                      <Field :name="+ index +`planned_start_date`" :rules="{ required: true }" v-slot="{ errors }">
                        <v-date-picker
                          v-model="item.PlanStartDate"
                          :min-date="StartDate"
                          :max-date="EndDate"
                          :format="'DD/MM/YYYY'"
                          class="input-group"
                        >
                          <template v-slot="{ inputValue, togglePopover }">
                            <input
                              placeholder="DD/MM/YYYY"
                              :value="inputValue"
                              class="form-control"
                              :class="{ 'is-invalid': errors.length > 0 }"
                              readonly
                            />
                            <div class="input-group-append" @click="togglePopover()" style="cursor: pointer">
                              <span class="input-group-text">
                                <em class="fa fa-calendar"></em>
                              </span>
                            </div>
                          </template>
                        </v-date-picker>
                      </Field>
                    </td>

                    <!-- Plan End Date -->
                    <td style="overflow:visible!important;">
                      <Field :name="+ index +`planned_end_date`" :rules="{ required: true }" v-slot="{ errors }">
                        <v-date-picker
                          v-model="item.PlanEndDate"
                          :min-date="item.PlanStartDate"
                          :max-date="EndDate"
                          :format="'DD/MM/YYYY'"
                          class="input-group"
                        >
                          <template v-slot="{ inputValue, togglePopover }">
                            <input
                              placeholder="DD/MM/YYYY"
                              :value="inputValue"
                              class="form-control"
                              :class="{ 'is-invalid': errors.length > 0 }"
                              readonly
                            />
                            <div class="input-group-append" @click="togglePopover()" style="cursor: pointer">
                              <span class="input-group-text">
                                <em class="fa fa-calendar"></em>
                              </span>
                            </div>
                          </template>
                        </v-date-picker>
                      </Field>
                    </td>

                    <td>
                      <Field :name="+ index + 'ParentTaskName'" v-slot="{ errors }">
                        <input type="text" class="form-control" v-model="item.ParentTaskName"
                          :class="['form-control disabled']" />
                      </Field>
                    </td>
                    <!-- Task Description -->
                    <td>
                      <Field :name="+ index + 'Description'" :rules="{ required: true }" v-slot="{ errors }">
                        <input type="text" class="form-control" v-model="item.TaskDescription"
                          :class="['form-control', { 'is-invalid': errors.length > 0 }]" />
                      </Field>
                    </td>

                    <td class="single-action">
                      <a href="javascript:void(0);" v-on:click="DeleteTaskItem(item, index)">
                        <em class="fa fa-trash text-danger"></em>
                      </a>
                    </td>
                  </tr>
                  <tr v-if="ListingData.length === 0">
                    <td colspan="20" class="text-center text-danger">
                      {{ $t('NoRecordfound') }}
                    </td>
                  </tr>
                </tbody>
              </table>
            </div>
            <div class="row flex-row-reverse mt-3">
              <div class="col-lg-6 text-right">
                <a href="javascript:;" title="Save" class="btn btn-success mr-1" v-on:click="OnSubmit()"><em class="fa fa-save pr-2"></em>{{ $t('Save') }}</a>
                <a href="javascript:;" title="AddMore" id="addMore" v-on:click="AddMore()" class="btn btn-info mr-1"><em class="fa fa-plus pr-2"></em>{{ $t('AddMore') }}</a>
                <a href="javascript:;" title="Cancel" class="btn btn-danger" v-on:click="RedirectToProjectDetails()"><em class="fa fa-close pr-2"></em>{{ $t('Cancel') }}</a>
              </div>
            </div>
          </div>
        </div>
      </Form>

    </div><!-- end border p-3 -->
</div>
    <!--Open Team Model-->
    <AddTeam v-if="IsAssignedUser" :ProjectId="ProjectId" :TaskId="ParentTaskId" :Type="IsType"
      :ProjectName="ProjectName" @close="IsAssignedUser = false;" @callbackfunction="FetchTaskList"></AddTeam>
    <GlobalTask v-if="isGlobalTask" :projectId="ProjectId" @cancel="Cancel" @next="selectedGlobalTeask">
    </GlobalTask>
    <AllowTime v-if="IsAllowTime" :projectId="ProjectId" :taskId="TaskId" @cancel="Cancel"></AllowTime>
  </section>
</template>

<script>
import GlobalTask from '../../../../components/Modal/GlobalTask.vue';
import DataService from '../../../../services/DataService.js';
import AddTeam from '../../../../components/Modal/AddTeam.vue';
import AllowTime from '../../../../components/Modal/AllowTime.vue';
export default {
  components: { GlobalTask, AddTeam, AllowTime },
  props: {
    UserId: {
      type: Number,
      required: false
    },
    GoalId: {
      type: Number,
      required: false
    },
    callbackfunction: {
      type: Function
    },
    GoalType: {
      type: String,
      required: false
    },
    GoalArray: {
      type: Array,
      required: false
    },
    projectId: {
      type: Number,
      required: false
    }
  },
  data() {
    return {
      IsType: 'task',
      proficiencyManager: 0,
      noRecord: false,
      TotalRecords: 0,
      isLoading: false,
      CommentList: [],
      weightagePersent: 0,
      progress: 0,
      startDate: '',
      endDate: '',
      isGlobalTask: false,
      ProficiencyHistoryList: [],
      attachmentName: '',
      oldattachmentName: '',
      file: '',
      excelFileName: '',
      filepath: '',
      expListing: [],
      ListingData: [],
      IsAssignedUser: false,
      ParentTaskId: null,
      projectHours: 0,
      PlanStartDate: '',
      PlanEndDate: '',
      selectAll: false,
      IsDisable: false,
      parenttaskdata: [],
      AllowTimeData: [],
      IsAllowTime: false,
      TaskId: 0,
      taskUserdata: [],
      StartDate: '',
      EndDate: '',
      selectedTaskIds: new Set(),
      // Phase 1 — tab state
      activeTab: 'excel',
      // Phase 2 — Jira CSV state
      jiraCsvFile: null,
      jiraCsvFileName: '',
      jiraCsvListing: [],
      ProjectId:0,
      // Phase 3 — Jira API state (credentials held in component only, never persisted)
      jiraCredentials: {
        domain: 'zorbisinc',
        email: '',
        apiToken: '',
        projectKey: 'TG'
      },
      jiraApiListing: [],
      isFetchingJira: false,
      Type:'Task'
    }
  },
  async created() {
    this.ProjectId = this.$route.params.projectId;
    this.projectHours = this.$route.params.projectHours;
    this.Type=this.$route.params.Type;
    this.oldattachmentName = '';
    await this.ProjectOverview();
  },
  watch: {
    items: {
      handler(newItems) {
        newItems.forEach(item => {
          if (
            item.PlanStartDate &&
            item.PlanEndDate &&
            new Date(item.PlanEndDate) < new Date(item.PlanStartDate)
          ) {
            this.StartDate = item.PlanStartDate;
            item.PlanEndDate = item.PlanStartDate;
          }
        });
      },
      deep: true
    }
  },
  computed: {
    groupByDate() {
      let groups = {};
      this.CommentList.forEach(item => {
        let date = item.CREATED_AT.substring(0, 10);
        if (groups[date]) {
          groups[date].push(item);
        } else {
          groups[date] = [item];
        }
      });
      return groups;
    },
    activePreviewList() {
      if (this.activeTab === 'excel') return this.expListing;
      if (this.activeTab === 'jiraCsv') return this.jiraCsvListing;
      if (this.activeTab === 'jiraApi') return this.jiraApiListing;
      return [];
    }
  },
  methods: {
     parseDescription(desc) {
    if (!desc) return '--';

    let data;

    // If string, convert to JSON
    try {
      data = typeof desc === 'string' ? JSON.parse(desc) : desc;
    } catch (e) {
      return desc; // fallback if not JSON
    }

    let text = '';
    let imageUrls = [];

    const traverse = (nodes) => {
      if (!nodes) return;

      nodes.forEach(node => {
        if (node.type === 'text') {
          text += node.text + ' ';
        }

        if (node.type === 'inlineCard' && node.attrs?.url) {
          imageUrls.push(node.attrs.url);
        }

        if (node.content) {
          traverse(node.content);
        }
      });
    };

    traverse(data.content);

    return {
      text: text.trim(),
      images: imageUrls
    };
  },
    // Phase 1 — tab management
    setActiveTab(tabName) {
      this.activeTab = tabName;
      this.expListing = [];
      this.attachmentName = '';
      this.file = '';
      this.excelFileName = '';
      this.filepath = '';
      this.jiraCsvListing = [];
      this.jiraCsvFile = null;
      this.jiraCsvFileName = '';
      this.jiraApiListing = [];
    },

    // Phase 2 — Jira CSV methods
    setJiraCsvFile(event) {
      const file = event.target.files[0];
      if (!file) return;
      const ext = file.name.split('.').pop().toLowerCase();
      if (ext !== 'csv') {
        this.ShowAlert(this.$t('InvalidFileType') || 'Please select a CSV file.', 'warning', true, this.$t('Alert') || 'Alert');
        event.target.value = '';
        return;
      }
      this.jiraCsvFile = file;
      this.jiraCsvFileName = file.name;
    },
    UploadJiraCsvFile() {
      if (!this.jiraCsvFile) {
        this.ShowAlert(this.$t('PleaseSelectFile') || 'Please select a CSV file.', 'warning', true, this.$t('Alert') || 'Alert');
        return;
      }
      var vm = this;
      const formdata = new FormData();
      formdata.append('file', this.jiraCsvFile);
      vm.isLoading = true;
      DataService.ImportJiraCsvPost(formdata).then(function (response) {
        if (response.data.status === 1) {
          DataService.GetJiraCsvTaskListing(vm.ProjectId).then(function (res) {
            vm.isLoading = false;
            if (res.data.status === 1 && res.data.listing) {
              vm.jiraCsvListing = res.data.listing.map(function (item) {
                return Object.assign({}, item, { selected: false, IsDisable: false });
              });
            }
          }).catch(function () {
            vm.isLoading = false;
            vm.ShowAlert('Failed to load Jira CSV tasks.', 'warning', true, vm.$t('Alert') || 'Alert');
          });
        } else {
          vm.isLoading = false;
          vm.ShowAlert(response.data.Msg || 'Failed to upload CSV.', 'warning', true, vm.$t('Alert') || 'Alert');
        }
      }).catch(function () {
        vm.isLoading = false;
        vm.ShowAlert('Failed to upload CSV file.', 'warning', true, vm.$t('Alert') || 'Alert');
      });
    },
    AddBulkFromPreview() {
      if (this.activeTab === 'excel') {
        this.AddBulkExcel();
      } else if (this.activeTab === 'jiraCsv') {
        this.AddBulkJiraCsv();
      } else if (this.activeTab === 'jiraApi') {
        this.AddBulkJiraApi();
      }
    },
    AddBulkJiraCsv() {
      var vm = this;
      var selected = this.jiraCsvListing.filter(function (x) { return x.selected && !x.IsDisable; });
      if (!selected.length) {
        this.ShowAlert(this.Type =='Task' ? this.$t('PleaseSelectAtleastOneTask') :  this.$t('PleaseSelectAtleastOneIssue'),'warning', true, this.$t('Alert') || 'Alert');
        return;
      }
      selected.forEach(function (item) {
        vm.ListingData.push({
          TOTAL_RECORDS: null,
          rowlevel: '',
          PARENT_TASK_LISTS: [],
          TaskId: null,
          ProjectId: vm.ProjectId,
          TaskName: item.TaskName || item.taskName || '',
          TaskDescription: vm.parseDescription(item.TaskDescription || item.taskDescription || '').text ,
          PlanStartDate: item.PlanStartDate || item.planStartDate || vm.StartDate,
          PlanEndDate: item.PlanEndDate || item.planEndDate || vm.EndDate,
          ParentTaskId: null,
