    // Helper: convert any date representation to local date string (YYYY-MM-DD) without timezone shift
    convertToLocalDateString(date) {
      if (!date) return '';
      // If already a YYYY-MM-DD string, return as-is
      if (typeof date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(date)) {
        return date;
      }
      const d = new Date(date);
      const year = d.getFullYear();
      const month = String(d.getMonth() + 1).padStart(2, '0');
      const day = String(d.getDate()).padStart(2, '0');
      return `${year}-${month}-${day}`;
    },
    OnSubmit: async function () {
      var vm = this;
      debugger
      const isValid = await this.$refs.form.validate();
      if (isValid) {
        const taskNames = vm.ListingData.map(function (item) { return (item.TaskName || '').trim().toLowerCase(); });
        const duplicates = taskNames.filter(function (name, index) {
          return taskNames.indexOf(name) !== index && name !== '';
        });
        vm.ListingData = vm.ListingData.map(function (item) {
          const taskName = (item.TaskName || '').trim().toLowerCase();
          return Object.assign({}, item, { isDuplicate: duplicates.includes(taskName) && taskName !== '' });
        });
        if (duplicates.length > 0) {
          vm.ShowAlert(vm.$t('DuplicateTaskNameFound'), 'failure', true, vm.$t('Alert'));
          return;
        }
        const invalidDate = vm.ListingData.some(function (item) {
          if (item.PlanStartDate && item.PlanEndDate) {
            const start = new Date(item.PlanStartDate);
            const end = new Date(item.PlanEndDate);
            start.setHours(0, 0, 0, 0);
            end.setHours(0, 0, 0, 0);
            return start > end;
          }
          return false;
        });
        if (invalidDate) {
          vm.ShowAlert(vm.$t('Enddatecannot'), "failure", true, vm.$t("Alert"));
          return;
        }
        vm.isLoading = true;
        // Convert dates to local YYYY-MM-DD strings to avoid timezone shift on JSON serialization
        const listingDataWithLocalDates = vm.ListingData.map(function (item) {
          return Object.assign({}, item, {
            PlanStartDate: vm.convertToLocalDateString(item.PlanStartDate),
            PlanEndDate: vm.convertToLocalDateString(item.PlanEndDate),
            AssignToAllTeamMember: item.AssignToAllTeamMember ? 1 : 0
          });
        });
        const postJSON = {
          ProjectId: vm.ProjectId,
          ProjectHours: vm.projectHours,
          MilestoneId: 0,
          taskData: listingDataWithLocalDates
        };
        const objectPostString = JSON.stringify(postJSON);
        try {
          const response = await DataService.SaveBulkUploadTask(objectPostString);
          vm.isLoading = false;
          if (response.data.result != null) {
            if (response.data.result == 0) {
              vm.ProjectData = response.data.result.ProjectData;
              vm.isProjectData = true;
              vm.RedirectToProjectDetails();
              vm.ShowAlert(vm.$t("AddedSuccess", [vm.Type =='Task' ? vm.$t('Task') : vm.$t('Issue')]), "success", true, vm.$t("Alert"));
            } else if (response.data.result == -2) {
              vm.ProjectData = response.data.result.ProjectData;
              vm.isProjectData = true;
              vm.ShowAlert(vm.$t("AlreadyExists", [vm.Type =='Task' ? vm.$t('Task') : vm.$t('Issue')]), "failure", true, vm.$t("Alert"));
            } else {
              vm.ShowAlert(vm.$t('UnknownErrorOccur'), "failure", true, vm.$t("Alert"));
            }
          }
        } catch (err) {
          vm.isLoading = false;
          vm.ShowAlert(vm.$t('UnknownErrorOccur'), "failure", true, vm.$t("Alert"));
        }
      } else {
        vm.ShowAlert(vm.$t('Please correct the highlighted errors.'), "failure", true, vm.$t("Alert"));
      }
    }
  }
}
</script>
